import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${select({ id: "arPreset", label: "Preset ratio", value: "custom", options: [{ label: "custom", value: "custom" },{ label: "16:9", value: "16:9" },{ label: "4:3", value: "4:3" },{ label: "1:1", value: "1:1" },{ label: "3:2", value: "3:2" },{ label: "21:9", value: "21:9" },{ label: "5:4", value: "5:4" },{ label: "2:3", value: "2:3" }]})}${field({ id: "arWidth", label: "Width", value: "16", type: "number" })}${field({ id: "arHeight", label: "Height", value: "9", type: "number" })}</div>`,generate(root) {const preset = root.querySelector("#arPreset").value;let width = parseInt(root.querySelector("#arWidth").value, 10) || 16;let height = parseInt(root.querySelector("#arHeight").value, 10) || 9;const presets = {"16:9": { w: 16, h: 9 },"4:3": { w: 4, h: 3 },"1:1": { w: 1, h: 1 },"3:2": { w: 3, h: 2 },"21:9": { w: 21, h: 9 },"5:4": { w: 5, h: 4 },"2:3": { w: 2, h: 3 }};if (preset !== "custom" && presets[preset]) {width = presets[preset].w;height = presets[preset].h;}const pbPercent = (height / width) * 100;const output = `.element {aspect-ratio: ${width} / ${height};width: 100%;}/* Fallback for older browsers */.element-fallback {position: relative;width: 100%;padding-bottom: ${pbPercent.toFixed(4)}%;}.element-fallback > .inner {position: absolute;inset: 0;}`;const preview = `<div style="width:100%;max-width:300px;margin:0 auto"><div style="aspect-ratio:${width}/${height};background:linear-gradient(135deg,#f97316,#ef4444);border-radius:4px;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700">${width}:${height}</div><p style="text-align:center;margin-top:4px;font-size:0.875rem;color:#6b7280">padding-bottom: ${pbPercent.toFixed(2)}%</p></div>`;return { output, preview };}};